query GroupsGetGolfTournamentGroups($input: GetGolfTournamentGroupsInput!) {
  getGolfTournamentGroups(input: $input) {
    roundNums
    groups {
      ...groupsGetGolfTournamentGroupsFieldsQuery
    }
  }
}
fragment groupsGetGolfTournamentGroupsFieldsQuery on GolfGroup {
  id
  groupNo
  hole
  status
  l1Course
  courseId
  startTime {
    time
  }
  teams {
    teamId
    players {
      id
      lastName
      firstName
    }
    roundScores {
      courseId
      startHole
      toParToday {
        value
      }
      holesThrough {
        value
      }
    }
    toPar {
      value
    }
    tournamentPosition {
      value
      displayValue
      format
    }
    status
    currentHole
  }
}
